import assert from "node:assert/strict";
import {createHash} from "node:crypto";
import {readFileSync,writeFileSync} from "node:fs";
import {gunzipSync} from "node:zlib";
const p=import.meta.dir,source=`${p}/..`,read=(f:string)=>JSON.parse(readFileSync(`${source}/${f}`,"utf8")),sha=(b:Buffer)=>createHash("sha256").update(b).digest("hex"),regraw=readFileSync(`${p}/registration.json`),reg=JSON.parse(regraw.toString()),primary=JSON.parse(readFileSync(`${p}/result.json`,"utf8")),ledger=read("data/case-ledger.json");
for(const f of reg.files)assert.equal(sha(readFileSync(`${source}/${f.path}`)),f.sha256);
const allGroups=new Map<string,Map<number,number>>(),folds:Record<string,unknown>={};
for(const fold of["train","validation"]){
 const groups=new Map<string,Map<number,number>>(),familySet=new Set<string>(),hist=new Map<number,number>();let records=0,aliased=0,maxSize=0,alt=0,altAliased=0,allowedAlt=0,upperRecords=0,validGroups=0,duplicateGroups=0;
 for(const line of gunzipSync(readFileSync(`${source}/data/${fold}.jsonl.gz`)).toString().trim().split("\n")){
  const r=JSON.parse(line);assert.equal(r.fold,fold);records++;const counts=new Map<string,number>();r.features.forEach((v:number[],i:number)=>{if(r.valid[i]){const key=JSON.stringify(v);counts.set(key,(counts.get(key)??0)+1);}});assert(r.valid[r.targetIndex]);const size=counts.get(JSON.stringify(r.features[r.targetIndex]))!;hist.set(size,(hist.get(size)??0)+1);aliased+=+(size>1);maxSize=Math.max(maxSize,size);validGroups+=counts.size;duplicateGroups+=[...counts.values()].filter(n=>n>1).length;
  const alternative=![r.cleanupIndex,r.outsideIndex].includes(r.targetIndex);alt+=+alternative;altAliased+=+(alternative&&size>1);if(alternative&&r.allowInference){allowedAlt++;if(size===1){upperRecords++;familySet.add(r.familyId);}}
  const key=JSON.stringify([r.features,r.valid,r.cleanupIndex,r.beforeIndex,r.outsideIndex,r.allowInference]);for(const map of[groups,allGroups]){const c=map.get(key)??new Map<number,number>();c.set(r.targetIndex,(c.get(r.targetIndex)??0)+1);map.set(key,c);}
 }
 const data={records,originalFamilies:new Set(ledger.filter((r:any)=>r.fold===fold).map((r:any)=>r.familyId)).size,targetHasIdenticalValidFeatureRival:aliased,targetFeatureGroupSizeHistogram:Object.fromEntries([...hist].sort(([a],[b])=>a-b)),largestTargetFeatureGroup:maxSize,validFeatureGroups:validGroups,duplicatedValidFeatureGroups:duplicateGroups,alternativeTeacherTargets:alt,aliasedAlternativeTeacherTargets:altAliased,completeInputAlternativeTeacherTargets:allowedAlt,structuralHighConfidenceCorrectAlternativeUpperBoundBeforeOod:upperRecords,structuralHighConfidenceCorrectAlternativeFamilyUpperBoundBeforeOod:familySet.size,distinctOrderedInputs:groups.size,repeatedOrderedInputs:[...groups.values()].filter(c=>[...c.values()].reduce((a,b)=>a+b,0)>1).length,contradictoryOrderedInputs:[...groups.values()].filter(c=>c.size>1).length,maximumDeterministicCorrectOnTheseObservedInputs:[...groups.values()].reduce((a,c)=>a+Math.max(...c.values()),0)};
 assert.deepEqual(data,primary.folds[fold]);folds[fold]=data;
}
const combined={records:Object.values(primary.folds).reduce((a:number,r:any)=>a+r.records,0),distinctOrderedInputs:allGroups.size,contradictoryOrderedInputs:[...allGroups.values()].filter(c=>c.size>1).length,maximumDeterministicCorrectOnTheseObservedInputs:[...allGroups.values()].reduce((a,c)=>a+Math.max(...c.values()),0)};assert.deepEqual(combined,primary.combined);assert.equal(primary.registrationSha256,sha(regraw));const out={passed:true,registrationSha256:sha(regraw),records:combined.records,allPrimaryIntegerCountsExact:true,testParsed:false,modelFitted:false,newIndependentStrengthSamples:0};writeFileSync(`${p}/independent-verification.json`,JSON.stringify(out,null,2)+"\n",{flag:"wx"});console.log(JSON.stringify(out));
